// The newest shelf whose day has arrived. An unknown or future day gets the
// current one rather than nothing.
function catalogFor(market) {
  let chosen = CATALOGS[0];
  for (const c of CATALOGS) if (String(market) >= c.from) chosen = c;
  return chosen.items;
}

// Only ever a fallback: a sale that never recorded what was in it is read
// against the current shelf.
const CATALOG = CATALOGS[CATALOGS.length - 1].items;

// A sale keeps its own record of what went in it. The catalog says what is in
// stock now, and that changes: an inventory update drops what sold out and was
// not restocked, and can reprice what remains. Reading history back through the
// current catalog made sold items disappear from past sales and made old sales
// silently adopt new prices.
function soldLines(entry) {
  return saleLines(entry, CATALOG);
}

function soldNamesOf(entry) {
  return saleNames(entry, CATALOG);
}

const CATEGORIES = ["All", "Hats", "Bags", "Charms", "Belts", "Rings", "Bracelets"];
const ENGAGEMENTS = ["Stopped", "Touched", "Asked", "Bought"];

// ─── IDENTITY ───
// Entries are keyed by uid, never by the display number. A uid is minted on the
// device that creates the entry and is never reused, so two phones adding a
// customer at the same moment produce two different customers.
const DEVICE_KEY = "ngd_device_id";

function getDeviceId() {
  try {
    let d = localStorage.getItem(DEVICE_KEY);
    if (!d) {
      d = Math.random().toString(36).slice(2, 8);
      localStorage.setItem(DEVICE_KEY, d);
    }
    return d;
  } catch { return "anon"; }
}

function makeUid(deviceId) {
  return Date.now().toString(36) + "-" + Math.random().toString(36).slice(2, 8) + "-" + deviceId;
}

// Entries written before uids existed are keyed off their old numeric id so
// every device derives the same uid for the same historical entry.
function withIdentity(e) {
  if (e.uid) return e;
  const when = e.createdAt || e.ts || new Date(0).toISOString();
  return { ...e, uid: "legacy-" + e.id, deviceId: e.deviceId || "legacy",
    createdAt: when, fieldTs: e.fieldTs || stampAll(when) };
}

// ─── SYNC ENGINE ───
// Fast enough that the other phone updates while you are still looking at it.
// Polling only runs while the app is on screen, so this costs less than the old
// 20s timer that ran regardless.
const SYNC_INTERVAL = 4000;
// Mobile networks routinely accept a connection and then never answer. Without
// a deadline such a request hangs forever, and because only one sync runs at a
// time that wedges syncing until the app is restarted, which is exactly what it
// looked like from the stall.
const SYNC_TIMEOUT = 12000;

function timeoutSignal(ms) {
  if (typeof AbortSignal !== "undefined" && typeof AbortSignal.timeout === "function") {
    return AbortSignal.timeout(ms);
  }
  const controller = new AbortController();
  setTimeout(() => controller.abort(), ms);
  return controller.signal;
}
const BASE_URL = "https://script.google.com/macros/s/";
function buildUrl(deployId) { return deployId ? BASE_URL + deployId + "/exec" : ""; }

function sortEntries(arr) {
  return [...arr].sort((a, b) => {
    const ka = a.createdAt || a.ts || "";
    const kb = b.createdAt || b.ts || "";
    if (ka !== kb) return kb.localeCompare(ka);
    return (b.id || 0) - (a.id || 0);
  });
}

// Tombstones older than a week are dropped so the payload does not grow forever.
const TOMBSTONE_TTL = 7 * 24 * 60 * 60 * 1000;
function pruneTombstones(entries) {
  const cutoff = Date.now() - TOMBSTONE_TTL;
  return entries.filter(e => !e.deletedAt || new Date(e.deletedAt).getTime() > cutoff);
}

function enrich(entries) {
  return entries.map(e => ({
    ...e,
    soldItemNames: soldNamesOf(e),
  }));
}

// Every network call reports what actually happened. The old code used
// mode: "no-cors", which made a rejected write look exactly like a successful
// one, so nothing could ever be retried.
//
// Some Apps Script deployments do not return readable CORS headers on POST. If
// that happens the request still reaches the script, so rather than calling it a
// failure we send it again in the old opaque mode and say plainly that the write
// could not be confirmed. setState always sends the full state, so sending it
// twice changes nothing.
async function postState(url, payload) {
  try {
    const res = await fetch(url, {
      method: "POST",
      headers: { "Content-Type": "text/plain;charset=utf-8" },
      body: JSON.stringify(payload),
    });
    if (!res.ok) return { ok: false, error: "sheet returned " + res.status };
    return { ok: true, confirmed: true };
  } catch {
    try {
      await fetch(url, {
        method: "POST", mode: "no-cors",
        headers: { "Content-Type": "text/plain;charset=utf-8" },
        body: JSON.stringify(payload),
      });
      return { ok: true, confirmed: false };
    } catch (e) {
      return { ok: false, error: e.message || "no connection" };
    }
  }
}

async function pushState(deployId, entries) {
  const url = buildUrl(deployId);
  if (!url) return { ok: false, error: "no sheet connected" };
  return postState(url, {
    action: "setState",
    state: { entries: enrich(entries), lastModified: new Date().toISOString() },
  });
}

async function pushLog(deployId, entry, action) {
  const url = buildUrl(deployId);
  if (!url) return { ok: false, error: "no sheet connected" };
  try {
    const res = await fetch(url, {
      method: "POST",
      headers: { "Content-Type": "text/plain;charset=utf-8" },
      body: JSON.stringify({
        action: "log",
        row: {
          timestamp: new Date().toISOString(),
          entryId: entry.id,
          uid: entry.uid || "",
          device: entry.deviceId || "",
          type: action,
          engage: entry.engage || "",
          amount: entry.amount || "",
          items: entry.items || "",
          soldItemNames: soldNamesOf(entry),
          payment: entry.payment || "",
          note: entry.note || "",
          raw: JSON.stringify(entry),
        },
      }),
    });
    if (!res.ok) return { ok: false, error: "sheet returned " + res.status };
    return { ok: true };
  } catch (e) {
    if (e.name === "TimeoutError" || e.name === "AbortError") {
      return { ok: false, error: "sync timed out" };
    }
    return { ok: false, error: e.message || "no connection" };
  }
}

// ─── WORKER SYNC ───
// Each entry is its own row on the server, so a push says "here are the three
// entries I changed" instead of "here is everything I know". Two phones adding
// customers at the same time no longer overwrite one another.
function makeStallKey() {
  const raw = (globalThis.crypto?.randomUUID?.() || Math.random().toString(36).slice(2) + Math.random().toString(36).slice(2));
  return raw.replace(/-/g, "").slice(0, 20);
}

function todayMarket(d = new Date()) {
  return d.getFullYear() + "-" + String(d.getMonth() + 1).padStart(2, "0") + "-" + String(d.getDate()).padStart(2, "0");
}

function cursorKey(stall, market) { return "ngd_cursor:" + stall + ":" + market; }

function syncBase(url) { return String(url).replace(/\/+$/, ""); }

function csvCell(value) {
  const text = value == null ? "" : String(value);
  return /[",\n\r]/.test(text) ? '"' + text.replace(/"/g, '""') + '"' : text;
}

// Mirrors the columns the server writes, so a backup taken on the phone and one
// downloaded from the server open the same way.
const EXPORT_COLUMNS = [
  ["number", e => e.id],
  ["time", e => e.time],
  ["engagement", e => e.engage],
  ["amount", e => e.amount],
  ["payment", e => e.payment],
  ["items sold", e => soldNamesOf(e)],
  ["items typed", e => e.items],
  ["note", e => e.note],
  ["phone", e => e.deviceId],
  ["created", e => e.createdAt],
  ["last edited", e => e.ts],
];

// Accepts our own export files and the older shape that had no uid, so a day
// saved before any of this existed can still be brought back.
function normaliseImported(raw) {
  if (!raw || typeof raw !== "object") return null;
  if (!raw.uid && !Number.isInteger(raw.id)) return null;
  const withUid = withIdentity({
    engage: "", amount: "", items: "", soldCatalogIds: [], payment: "", note: "", time: "",
    ...raw,
  });
  return {
    ...withUid,
    deletedAt: raw.deletedAt || null,
    createdAt: withUid.createdAt || withUid.ts || new Date().toISOString(),
    ts: withUid.ts || new Date().toISOString(),
  };
}

function readImportFile(text) {
  const parsed = JSON.parse(text);
  const rows = Array.isArray(parsed) ? parsed : parsed.entries;
  if (!Array.isArray(rows)) throw new Error("no entries in that file");
  const entries = rows.map(normaliseImported).filter(Boolean);
  if (entries.length === 0) throw new Error("no entries in that file");
  const market = (!Array.isArray(parsed) && parsed.market) ||
    (entries[0].createdAt || entries[0].ts || "").slice(0, 10);
  return { market, entries };
}

function toCsv(entries) {
  const lines = [EXPORT_COLUMNS.map(c => csvCell(c[0])).join(",")];
  entries.forEach(e => lines.push(EXPORT_COLUMNS.map(c => csvCell(c[1](e))).join(",")));
  // The byte order mark stops Excel mangling the Chinese item names.
  return "\ufeff" + lines.join("\r\n") + "\r\n";
}

// Saves a file from what is already on this phone, so a backup can be taken
// with no signal at all.
function downloadFile(name, text, type) {
  try {
    const blob = new Blob([text], { type });
    const href = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = href;
    link.download = name;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    setTimeout(() => URL.revokeObjectURL(href), 2000);
    return true;
  } catch { return false; }
}

// Two people editing one customer are usually editing different things: she
// marks the sale, he writes the note. Without knowing which field each of them
// actually touched, the server can only keep the newer whole entry and the
// other person's work disappears. So every change records its own field.
const MERGEABLE = [
  "time", "engage", "amount", "amountManual", "payment",
  "items", "soldCatalogIds", "soldItems", "soldItemNames", "note",
];

function stampFor(stamps, field, fallback) {
  const t = stamps && typeof stamps[field] === "string" ? stamps[field] : null;
  return t || fallback;
}

function stampAll(when) {
  const stamps = {};
  MERGEABLE.forEach(f => { stamps[f] = when; });
  stamps.deletedAt = when;
  return stamps;
}

// Marks just the fields this change touched, leaving the rest as they were.
function touch(entry, fields, when) {
  const base = entry.fieldTs || stampAll(entry.createdAt || entry.ts || when);
  const next = { ...base };
  fields.forEach(f => { next[f] = when; });
  return next;
}

// The same merge the server does, so an unsent local edit is not thrown away by
// a version arriving from the other phone.
function mergeEntryFields(mine, theirs) {
  const merged = { ...mine };
  MERGEABLE.forEach(field => {
    const a = stampFor(mine.fieldTs, field, mine.ts);
    const b = stampFor(theirs.fieldTs, field, theirs.ts);
    if (field in theirs && b > a) merged[field] = theirs[field];
  });
  const mineDel = stampFor(mine.fieldTs, "deletedAt", mine.ts);
  const theirsDel = stampFor(theirs.fieldTs, "deletedAt", theirs.ts);
  if (theirsDel > mineDel || (theirsDel === mineDel && theirs.deletedAt && !mine.deletedAt)) {
    merged.deletedAt = theirs.deletedAt || null;
  }
  const fieldTs = {};
  [...MERGEABLE, "deletedAt"].forEach(field => {
    const a = stampFor(mine.fieldTs, field, mine.ts);
    const b = stampFor(theirs.fieldTs, field, theirs.ts);
    fieldTs[field] = b > a ? b : a;
  });
  return { ...merged, fieldTs, ts: theirs.ts > mine.ts ? theirs.ts : mine.ts };
}

// The server owns the display number, so whichever side wins on content, the
// number comes from the server. That is what stops two phones showing #12 twice.
function mergeFromServer(local, remote) {
  const byUid = new Map(local.map(e => [e.uid, e]));
  remote.forEach(r => {
    const l = byUid.get(r.uid);
    if (!l) { byUid.set(r.uid, r); return; }
    byUid.set(r.uid, { ...mergeEntryFields(l, r), id: r.id ?? l.id });
  });
  return sortEntries(Array.from(byUid.values()));
}

// One round trip does both directions: it sends what changed here and returns
// what changed anywhere else since the cursor.
async function syncWithWorker({ url, stall, market, since, rows }) {
  const base = String(url).replace(/\/+$/, "");
  const endpoint = base + "/sync?stall=" + encodeURIComponent(stall) +
    "&market=" + encodeURIComponent(market) + "&since=" + since;
  try {
    const res = rows.length
      ? await fetch(endpoint, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ rows }),
          signal: timeoutSignal(SYNC_TIMEOUT),
        })
      : await fetch(endpoint, { signal: timeoutSignal(SYNC_TIMEOUT) });
    if (!res.ok) {
      let message = "sync returned " + res.status;
      try { const body = await res.json(); if (body?.error) message = body.error; } catch { /* keep the status */ }
      return { ok: false, error: message };
    }
    const data = await res.json();
    return {
      ok: true,
      cursor: Number(data.cursor) || 0,
      rows: Array.isArray(data.rows) ? data.rows : [],
    };
  } catch (e) {
    return { ok: false, error: e.message || "no connection" };
  }
}

// Read straight into the first render. The old code loaded in an effect, and the
// save effect fired in the same commit with an empty list, briefly overwriting
// the saved day.
function loadSavedEntries() {
  let loaded = [];
  try {
    const saved = localStorage.getItem("ngd_entries");
    if (saved) loaded = JSON.parse(saved).map(e => withIdentity(e));
  } catch { /* storage unavailable, carry on */ }

  // One time migration. Deletions used to live in a local only list, which is
  // why deleted entries kept coming back from the other phone. Turn them into
  // real tombstones so they can travel.
  try {
    const old = localStorage.getItem("ngd_deleted");
    if (old) {
      const now = new Date().toISOString();
      const have = new Set(loaded.map(e => e.uid));
      JSON.parse(old).forEach(id => {
        const uid = "legacy-" + id;
        if (have.has(uid)) return;
        loaded.push({ uid, id, deviceId: "legacy", time: "", engage: "", amount: "", items: "",
          soldCatalogIds: [], payment: "", note: "", createdAt: now, ts: now, deletedAt: now });
      });
      localStorage.removeItem("ngd_deleted");
    }
  } catch { /* storage unavailable, carry on */ }

  return sortEntries(loaded);
}

function loadStr(key) {
  try { return localStorage.getItem(key) || ""; } catch { return ""; }
}

function saveStr(key, value) {
  try { localStorage.setItem(key, value); } catch { /* storage unavailable, carry on */ }
}

function loadDeployId() { return loadStr("ngd_deploy_id"); }

// Generated once per stall, then shared with the other phones. It is both the
// namespace on the server and the only thing keeping the data private, which is
// why it is long and random rather than something memorable.
function loadStallKey() {
  const existing = loadStr("ngd_stall_key");
  if (existing) return existing;
  const fresh = makeStallKey();
  saveStr("ngd_stall_key", fresh);
  return fresh;
}

function loadMarket() {
  return loadStr("ngd_market") || todayMarket();
}

// Setting up the second phone by typing a twenty character key on a phone
// keyboard is miserable, so the settings screen can hand over a link that
// carries the whole configuration instead.
function setupParams() {
  try { return new URLSearchParams(window.location.search); } catch { return new URLSearchParams(); }
}

function buildSetupLink(syncUrl, stallKey, market) {
  try {
    const u = new URL(window.location.href);
    u.search = "";
    u.hash = "";
    const q = new URLSearchParams({ sync: syncUrl, stall: stallKey, market });
    return u.toString() + "?" + q.toString();
  } catch { return ""; }
}

// Entries changed here but not yet accepted by the server.
function loadDirty() {
  try {
    const raw = localStorage.getItem("ngd_dirty");
    return new Set(raw ? JSON.parse(raw) : []);
  } catch { return new Set(); }
}

const GearIcon = () => (
  <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="#1a1a1a" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
    <circle cx="12" cy="12" r="3" />
    <path d="M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 1 1-2.83 2.83l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 0 1-4 0v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 1 1-2.83-2.83l.06-.06A1.65 1.65 0 0 0 4.68 15a1.65 1.65 0 0 0-1.51-1H3a2 2 0 0 1 0-4h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 1 1 2.83-2.83l.06.06A1.65 1.65 0 0 0 9 4.68a1.65 1.65 0 0 0 1-1.51V3a2 2 0 0 1 4 0v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 1 1 2.83 2.83l-.06.06A1.65 1.65 0 0 0 19.4 9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 0 1 0 4h-.09a1.65 1.65 0 0 0-1.51 1z" />
  </svg>
);
export default function App() {
  const [tab, setTab] = useState("count");
  const [entries, setEntries] = useState(loadSavedEntries);
  const [expandedUid, setExpandedUid] = useState(null);
  const [showSettings, setShowSettings] = useState(false);
  const [search, setSearch] = useState("");
  const [catFilter, setCatFilter] = useState("All");
  const [showCatalogPicker, setShowCatalogPicker] = useState(null);
  const [pickerCat, setPickerCat] = useState("All");
  const [syncStatus, setSyncStatus] = useState("");
  const [syncError, setSyncError] = useState("");

  // Worker sync
  const [syncUrl, setSyncUrl] = useState(() => setupParams().get("sync") || loadStr("ngd_sync_url"));
  const [stallKey, setStallKey] = useState(() => setupParams().get("stall") || loadStallKey());
  const [market, setMarket] = useState(() => setupParams().get("market") || loadMarket());
  const [dirty, setDirty] = useState(loadDirty);

  // The Google Sheet is now an export, not the database
  const [deployId, setDeployId] = useState(loadDeployId);

  const [deviceId] = useState(getDeviceId);
  const [history, setHistory] = useState(null);
  const [historyError, setHistoryError] = useState("");
  // Every day the server holds, so this phone can notice that another one has
  // already started a new market.
  const [serverDays, setServerDays] = useState([]);
  const fileInput = useRef(null);
  const entriesRef = useRef(entries);
  const dirtyRef = useRef(dirty);
  const unsentCountRef = useRef(0);
  const cfgRef = useRef({ syncUrl, stallKey, market });
  const syncing = useRef(false);
  // Uids that came back from a backup file and have not reached the server yet.
  // Their customer numbers are part of the record, so the push that carries
  // them asks the server to keep them rather than hand out new ones.
  const restored = useRef(new Set());

  // The shelf for the day being looked at. Opening March shows March's stock and
  // March's prices, not what is on the table now.
  const catalog = catalogFor(market);
  useEffect(() => { entriesRef.current = entries; }, [entries]);
  useEffect(() => { dirtyRef.current = dirty; }, [dirty]);
  useEffect(() => { unsentCountRef.current = dirty.size; }, [dirty]);
  useEffect(() => { cfgRef.current = { syncUrl, stallKey, market }; }, [syncUrl, stallKey, market]);

  // The stall key is a secret, so it does not stay sitting in the address bar
  // where it would end up in history and in screenshots.
  useEffect(() => {
    if (!window.location.search) return;
    try { window.history.replaceState({}, "", window.location.pathname); } catch { /* history unavailable, carry on */ }
  }, []);

  // ── save ──
  useEffect(() => {
    try { localStorage.setItem("ngd_entries", JSON.stringify(entries)); } catch { /* storage unavailable, carry on */ }
  }, [entries]);
  useEffect(() => { saveStr("ngd_sync_url", syncUrl); }, [syncUrl]);
  useEffect(() => { saveStr("ngd_stall_key", stallKey); }, [stallKey]);
  useEffect(() => { saveStr("ngd_market", market); }, [market]);
  useEffect(() => { saveStr("ngd_deploy_id", deployId); }, [deployId]);
  useEffect(() => {
    try { localStorage.setItem("ngd_dirty", JSON.stringify([...dirty])); } catch { /* storage unavailable, carry on */ }
  }, [dirty]);

  const syncConfigured = Boolean(syncUrl && stallKey && market);

  // While a panel is open the page behind is held still. On a phone the scroll
  // otherwise chains through to it and the whole screen drifts.
  const panelOpen = showSettings || showCatalogPicker !== null;
  useEffect(() => {
    if (!panelOpen) return;
    const previous = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => { document.body.style.overflow = previous; };
  }, [panelOpen]);

  const markDirty = useCallback((uid) => {
    setDirty(prev => (prev.has(uid) ? prev : new Set(prev).add(uid)));
  }, []);

  // ── sync ──
  // Sends only what changed here, receives only what changed elsewhere. Anything
  // that fails to send stays in the queue and goes out on the next attempt, so a
  // dead spot at the stall costs nothing.
  const runSync = useCallback(async (manual) => {
    const { syncUrl: url, stallKey: stall, market: day } = cfgRef.current;
    if (!url || !stall || !day || syncing.current) return;
    syncing.current = true;
    if (manual) setSyncStatus("syncing…");

    try {
      const queued = dirtyRef.current;
      // The server has no catalog, so carry readable item names along with the
      // ids. Without them an exported backup is a list of codes.
      const outgoing = entriesRef.current.filter(e => queued.has(e.uid)).map(e => ({
        ...e,
        soldItemNames: soldNamesOf(e),
        ...(restored.current.has(e.uid) ? { keepNumber: true } : {}),
      }));
      const sentAt = new Map(outgoing.map(e => [e.uid, e.ts]));

      let since = 0;
      try { since = parseInt(localStorage.getItem(cursorKey(stall, day)) || "0", 10) || 0; } catch { /* storage unavailable, carry on */ }

      const result = await syncWithWorker({ url, stall, market: day, since, rows: outgoing });

      if (!result.ok) {
        setSyncError(result.error);
        setSyncStatus("");
        return;
      }

      try { localStorage.setItem(cursorKey(stall, day), String(result.cursor)); } catch { /* storage unavailable, carry on */ }
      if (result.rows.length) setEntries(prev => pruneTombstones(mergeFromServer(prev, result.rows)));

      // Only clear what was actually sent, and only if it has not been edited
      // again while the request was in flight.
      setDirty(prev => {
        const next = new Set(prev);
        sentAt.forEach((ts, uid) => {
          const now = entriesRef.current.find(e => e.uid === uid);
          if (!now || now.ts === ts) { next.delete(uid); restored.current.delete(uid); }
        });
        return next;
      });

      setSyncError("");
      // A badge that reappears every few seconds is noise, so only a sync the
      // user asked for gets confirmed on screen.
      if (manual) {
        setSyncStatus("synced");
        setTimeout(() => setSyncStatus(t => (t === "synced" ? "" : t)), 1500);
      } else {
        setSyncStatus("");
      }
    } finally {
      // Whatever went wrong above, the next sync must be allowed to start.
      syncing.current = false;
    }
  }, []);

  // Sync while the app is on screen, and the moment it comes back. Phone
  // browsers freeze timers when the screen locks or you switch apps, which is
  // why a background timer alone made it look like sync only worked on restart.
  useEffect(() => {
    if (!syncConfigured) return;
    let timer = null;
    const start = () => { if (!timer) timer = setInterval(() => runSync(false), SYNC_INTERVAL); };
    const stop = () => { if (timer) { clearInterval(timer); timer = null; } };
    const resume = () => {
      if (document.visibilityState === "hidden") { stop(); return; }
      runSync(false);
      start();
    };
    const first = setTimeout(() => runSync(false), 200);
    start();
    document.addEventListener("visibilitychange", resume);
    window.addEventListener("online", resume);
    window.addEventListener("focus", resume);
    window.addEventListener("pageshow", resume);
    return () => {
      clearTimeout(first);
      stop();
      document.removeEventListener("visibilitychange", resume);
      window.removeEventListener("online", resume);
      window.removeEventListener("focus", resume);
      window.removeEventListener("pageshow", resume);
    };
  }, [syncConfigured, runSync]);

  // Anything changed here goes out almost immediately rather than waiting for
  // the next tick. A failed send leaves the queue untouched, so this cannot
  // spin while there is no signal.
  useEffect(() => {
    if (!syncConfigured || dirty.size === 0) return;
    const t = setTimeout(() => runSync(false), 700);
    return () => clearTimeout(t);
  }, [dirty, syncConfigured, runSync]);

  const logAction = useCallback((entry, action) => {
    if (entry && deployId) pushLog(deployId, entry, action);
  }, [deployId]);

  // A provisional number so the entry reads correctly before it has synced. The
  // server replaces it with one that is unique across every phone.
  const claimNumber = useCallback((current) => {
    let stored = 0;
    try { stored = parseInt(localStorage.getItem("ngd_seq") || "0", 10) || 0; } catch { /* storage unavailable, carry on */ }
    const highest = current.reduce((m, e) => Math.max(m, e.id || 0), 0);
    const next = Math.max(stored, highest) + 1;
    try { localStorage.setItem("ngd_seq", String(next)); } catch { /* storage unavailable, carry on */ }
    return next;
  }, []);

  const addEntry = useCallback(() => {
    const now = new Date();
    const entry = {
      uid: makeUid(deviceId),
      deviceId,
      id: claimNumber(entries),
      time: now.toLocaleTimeString("en-US", { hour: "numeric", minute: "2-digit" }),
      engage: "", amount: "", amountManual: false, items: "", soldCatalogIds: [],
      payment: "", note: "",
      createdAt: now.toISOString(), ts: now.toISOString(), deletedAt: null,
      fieldTs: stampAll(now.toISOString()),
    };
    setEntries(prev => sortEntries([entry, ...prev]));
    setExpandedUid(entry.uid);
    markDirty(entry.uid);
    logAction(entry, "add");
  }, [entries, deviceId, claimNumber, markDirty, logAction]);

  const deleteEntry = useCallback((uid) => {
    const stamp = new Date().toISOString();
    setEntries(prev => prev.map(e =>
      (e.uid === uid ? { ...e, deletedAt: stamp, ts: stamp, fieldTs: touch(e, ["deletedAt"], stamp) } : e)));
    setExpandedUid(null);
    markDirty(uid);
    const entry = entriesRef.current.find(e => e.uid === uid);
    if (entry) logAction({ ...entry, deletedAt: stamp }, "delete");
  }, [markDirty, logAction]);

  // Removes the newest entry this phone created, never whatever happens to be at
  // the top of a merged list.
  const undoEntry = useCallback(() => {
    const mine = entries.filter(e => !e.deletedAt && e.deviceId === deviceId);
    if (mine.length === 0) return;
    deleteEntry(mine[0].uid);
  }, [entries, deviceId, deleteEntry]);

  const updateEntry = useCallback((uid, field, value) => {
    setEntries(prev => prev.map(e => {
      if (e.uid !== uid) return e;
      const now = new Date().toISOString();
      const touched = field === "amount" ? [field, "amountManual"] : [field];
      const patch = { [field]: value, ts: now, fieldTs: touch(e, touched, now) };
      if (field === "amount") patch.amountManual = true;
      return { ...e, ...patch };
    }));
    markDirty(uid);
  }, [markDirty]);

  const saveAndCollapse = useCallback((uid) => {
    setExpandedUid(null);
    const entry = entriesRef.current.find(e => e.uid === uid);
    if (entry) logAction(entry, "update");
    runSync(false);
  }, [logAction, runSync]);

  const toggleSoldItem = useCallback((uid, catalogId) => {
    setEntries(prev => prev.map(e => {
      if (e.uid !== uid) return e;
      const ids = e.soldCatalogIds || [];
      const next = ids.includes(catalogId) ? ids.filter(x => x !== catalogId) : [...ids, catalogId];
      const sum = next.reduce((t, cid) => { const c = catalog.find(x => x.id === cid); return t + (c?.price || 0); }, 0);
      const now = new Date().toISOString();
      const base = ["soldCatalogIds", "soldItems", "soldItemNames"];
      const touched = e.amountManual ? base : [...base, "amount"];
      // Recorded at the price it sold for, so a later repricing does not rewrite
      // what already happened.
      const soldItems = next.map(cid => {
        const kept = (e.soldItems || []).find(i => i.id === cid);
        if (kept) return kept;
        const c = catalog.find(x => x.id === cid);
        return c ? snapshotOf(c) : { id: cid, name: cid, price: null };
      });
      return {
        ...e,
        soldCatalogIds: next,
        soldItems,
        amount: e.amountManual ? e.amount : String(sum),
        ts: now,
        fieldTs: touch(e, touched, now),
      };
    }));
    markDirty(uid);
  }, [markDirty, catalog]);

  // ── derived ──
  const visible = entries.filter(e => !e.deletedAt);

  // Stock is counted, not flagged, so an item with two units survives one sale.
  const soldCounts = new Map();
  visible.forEach(e => (e.soldCatalogIds || []).forEach(id => soldCounts.set(id, (soldCounts.get(id) || 0) + 1)));
  const soldOutIds = new Set();
  catalog.forEach(item => { if ((soldCounts.get(item.id) || 0) >= (item.qty || 1)) soldOutIds.add(item.id); });

  const totalCount = visible.length;
  const boughtCount = visible.filter(e => e.engage === "Bought").length;
  const totalRevenue = visible.reduce((s, e) => {
    if (e.engage !== "Bought") return s;
    const a = parseFloat(e.amount);
    return s + (isNaN(a) ? 0 : a);
  }, 0);

  // Scoped to the market day that is loaded, never a running total.
  const stats = tab === "numbers" ? computeStats(visible, catalog) : null;

  const unsentCount = dirty.size;
  // Today wins if the calendar has moved on. Otherwise, if another phone has
  // already opened a later day, follow that one.
  const today = todayMarket();
  const laterOnServer = serverDays.filter(d => d > market).sort().pop();
  const suggestedDay = today > market ? today : (laterOnServer || null);
  const suggestedReason = today > market ? "It is a new day" : "Another phone has started";

  const exportToSheet = async () => {
    if (!deployId) return;
    setSyncStatus("exporting…");
    const result = await pushState(deployId, visible);
    setSyncStatus(result.ok ? (result.confirmed ? "exported" : "sent") : "export failed");
    setTimeout(() => setSyncStatus(""), 2500);
  };

  const downloadToday = () => {
    const ok = downloadFile("nogooddesign-" + market + ".csv", toCsv(visible), "text/csv;charset=utf-8");
    setSyncStatus(ok ? "saved" : "save failed");
    setTimeout(() => setSyncStatus(""), 2500);
  };

  const downloadTodayJson = () => {
    const payload = { market, exported: new Date().toISOString(), entries: visible };
    const ok = downloadFile("nogooddesign-" + market + ".json", JSON.stringify(payload, null, 2), "application/json");
    setSyncStatus(ok ? "saved" : "save failed");
    setTimeout(() => setSyncStatus(""), 2500);
  };

  const exportUrl = (day, format) =>
    syncBase(syncUrl) + "/export?stall=" + encodeURIComponent(stallKey) +
    "&market=" + encodeURIComponent(day) + "&format=" + format;

  const fetchDays = useCallback(async () => {
    const { syncUrl: url, stallKey: stall } = cfgRef.current;
    if (!url || !stall) return [];
    try {
      const res = await fetch(syncBase(url) + "/markets?stall=" + encodeURIComponent(stall),
        { signal: timeoutSignal(SYNC_TIMEOUT) });
      if (!res.ok) return [];
      const data = await res.json();
      return Array.isArray(data.markets) ? data.markets : [];
    } catch { return []; }
  }, []);

  // Checked on load and occasionally after, so if the other phone starts a new
  // market this one offers to follow rather than quietly counting into
  // yesterday.
  useEffect(() => {
    if (!syncConfigured) return;
    let alive = true;
    const look = () => fetchDays().then(days => { if (alive) setServerDays(days.map(d => d.market)); });
    const first = setTimeout(look, 1500);
    const timer = setInterval(look, 5 * 60 * 1000);
    return () => { alive = false; clearTimeout(first); clearInterval(timer); };
  }, [syncConfigured, fetchDays]);

  const loadHistory = async () => {
    if (!syncConfigured) return;
    setHistoryError("");
    setHistory(null);
    try {
      const res = await fetch(syncBase(syncUrl) + "/markets?stall=" + encodeURIComponent(stallKey),
        { signal: timeoutSignal(SYNC_TIMEOUT) });
      if (!res.ok) { setHistoryError("could not load history"); return; }
      const data = await res.json();
      setHistory(Array.isArray(data.markets) ? data.markets : []);
    } catch {
      setHistoryError("could not reach the server");
    }
  };

  const restoreFromFile = async (file) => {
    if (!file) return;
    try {
      const { market: fileMarket, entries: imported } = readImportFile(await file.text());
      const day = fileMarket || market;
      const live = imported.filter(e => !e.deletedAt).length;
      if (!confirm("Bring back " + live + " customers into " + day + "?" +
        (day !== market ? " This phone will switch to that day." : ""))) return;

      if (day !== market) {
        // Restoring into a different day starts from the file alone. Merging
        // would carry this day's customers across into that one, which is
        // exactly the piling up that separate market days exist to prevent.
        try { localStorage.removeItem(cursorKey(stallKey, day)); } catch { /* storage unavailable, carry on */ }
        setMarket(day);
        setExpandedUid(null);
        setHistory(null);
        setEntries(sortEntries(imported));
      } else {
        // Into the same day it is a merge, so a file can fill in what was lost
        // without throwing away what is here.
        setEntries(prev => sortEntries(mergeFromServer(prev, imported)));
      }
      // Imported entries carry stable uids, so restoring the same file twice
      // cannot double anything.
      setDirty(prev => {
        const next = new Set(prev);
        imported.forEach(e => next.add(e.uid));
        return next;
      });
      imported.forEach(e => restored.current.add(e.uid));
      setSyncStatus("restored " + live);
      setTimeout(() => setSyncStatus(""), 3000);
    } catch (e) {
      setSyncStatus(e.message === "no entries in that file" ? "nothing to restore" : "could not read that file");
      setTimeout(() => setSyncStatus(""), 3000);
    }
  };

  const copySetupLink = async () => {
    const link = buildSetupLink(syncUrl, stallKey, market);
    if (!link) return;
    try {
      await navigator.clipboard.writeText(link);
      setSyncStatus("link copied");
    } catch {
      setSyncStatus("copy failed");
    }
    setTimeout(() => setSyncStatus(""), 2500);
  };

  // Moving to another day is the same operation whether it is a new market or
  // catching up with the other phone: point at the day, and start empty so the
  // list is not two markets stacked on top of each other. Nothing is destroyed,
  // the old day stays on the server.
  const switchToDay = useCallback((day) => {
    if (!day || day === market) return;
    if (unsentCountRef.current > 0 &&
        !confirm("This phone still has " + unsentCountRef.current + " unsent. Switching to " + day + " leaves them unsent. Continue?")) {
      return;
    }
    // The cursor for that day has to go with the entries. Keeping it would mean
    // asking the server for "anything since I last looked", getting nothing,
    // and sitting on an empty list for a day that is not empty.
    try { localStorage.removeItem(cursorKey(stallKey, day)); } catch { /* storage unavailable, carry on */ }
    setMarket(day);
    setEntries([]);
    setDirty(new Set());
    setExpandedUid(null);
    setHistory(null);
  }, [market, stallKey]);

  const startNewMarket = () => {
    const today = todayMarket();
    if (today === market) return;
    if (!confirm("Start " + today + "? This phone's list clears. " + market + " stays on the server.")) return;
    switchToDay(today);
  };

  const clearData = () => {
    if (confirm("Clear this phone's copy? The server keeps everything, and the next sync pulls it back.")) {
      setEntries([]);
      setExpandedUid(null);
      // Without this the queue keeps uids for entries that no longer exist, and
      // the "waiting to send" count never comes back down.
      setDirty(new Set());
      try { localStorage.removeItem(cursorKey(stallKey, market)); } catch { /* storage unavailable, carry on */ }
    }
  };

  const filteredCatalog = catalog.filter(item => {
    const matchCat = catFilter === "All" || item.category === catFilter;
    const q = search.trim().toLowerCase();
    const matchSearch = !q || item.name.toLowerCase().includes(q) ||
      (item.price != null && String(item.price) === q.replace(/^\$/, ""));
    return matchCat && matchSearch;
  });
  const grouped = {};
  filteredCatalog.forEach(item => { if (!grouped[item.category]) grouped[item.category] = []; grouped[item.category].push(item); });
  // Dearest first inside each category. Catalog order is an accident of when a
  // piece was bought, which reads as jumbled when someone is scanning for a price.
  Object.values(grouped).forEach(list => list.sort((a, b) =>
    (b.price ?? -1) - (a.price ?? -1) || a.name.localeCompare(b.name)));

  return (
    <div style={S.shell}>
      <style>{`
        * { margin: 0; padding: 0; box-sizing: border-box; }
        input::placeholder { color: #a09a92; }
        input[type="number"]::-webkit-inner-spin-button { -webkit-appearance: none; }
        ::-webkit-scrollbar { width: 0; }
      `}</style>

      {/* CATALOG PICKER MODAL */}
      {showCatalogPicker !== null && (
        <div style={S.overlay} onClick={() => { setShowCatalogPicker(null); setPickerCat("All"); }}>
          <div style={S.pickerModal} onClick={e => e.stopPropagation()}>
            <div style={S.pickerHead}>
              <span style={S.pickerTitle}>What sold?</span>
              <button style={S.closeBtn} onClick={() => { setShowCatalogPicker(null); setPickerCat("All"); }}>✕</button>
            </div>
            <div style={S.rule} />
            <div style={S.catRow}>
              {CATEGORIES.map(c => (
                <button key={c} style={pickerCat === c ? S.catActive : S.catBtn} onClick={() => setPickerCat(c)}>{c}</button>
              ))}
            </div>
            <div style={S.rule} />
            <div style={S.pickerList}>
              {catalog.filter(c => pickerCat === "All" || c.category === pickerCat).map(item => {
                const entry = visible.find(e => e.uid === showCatalogPicker);
                const isSelected = entry?.soldCatalogIds?.includes(item.id);
                const isSoldByOther = soldOutIds.has(item.id) && !isSelected;
                return (
                  <div key={item.id} style={{ ...S.pickerItem, textDecoration: isSoldByOther ? "line-through" : "none" }}
                    onClick={() => !isSoldByOther && toggleSoldItem(showCatalogPicker, item.id)}>
                    <div style={S.pickerCheck}>{isSelected ? "■" : "□"}</div>
                    <div style={S.pickerThumb}>
                      {IMAGES[item.id] ? <img src={IMAGES[item.id]} style={S.thumbImg} alt="" /> : <div style={S.thumbFallback}>?</div>}
                    </div>
                    <span style={S.pickerName}>{item.name}</span>
                    <span style={S.pickerPrice}>{item.price ? `$${item.price}` : "—"}</span>
                  </div>
                );
              })}
            </div>
            <button style={S.pickerDoneBtn} onClick={() => { setShowCatalogPicker(null); setPickerCat("All"); }}>Done</button>
          </div>
        </div>
      )}

      {/* SETTINGS */}
      {showSettings && (
        <div style={S.overlay} onClick={() => setShowSettings(false)}>
          <div style={S.modal} onClick={e => e.stopPropagation()}>
            <div style={S.modalHead}>
              <span style={S.modalTitle}>Settings</span>
              <button style={S.closeBtn} onClick={() => setShowSettings(false)}>✕</button>
            </div>
            <div style={S.rule} />
            <div style={S.modalBody}>
            <label style={S.label}>Sync address</label>
            <input style={S.modalInput} value={syncUrl} inputMode="url"
              onChange={e => setSyncUrl(e.target.value.trim())}
              placeholder="https://nogooddesign-sync.workers.dev" />
            <p style={S.hint}>Paste the same address into every phone</p>

            <label style={S.label}>Stall key</label>
            <input style={S.modalInput} value={stallKey}
              onChange={e => setStallKey(e.target.value.trim())} placeholder="20 characters" />
            <p style={S.hint}>
              Your phones share this. It keeps the stall private, so treat it like a password.
            </p>

            <label style={S.label}>Market day</label>
            <input style={S.modalInput} type="date" value={market}
              onChange={e => e.target.value && switchToDay(e.target.value)} />
            <p style={S.hint}>
              Each market day is counted separately, so days never pile up together.
            </p>
            {market !== todayMarket() && (
              <button style={S.modalBtn} onClick={startNewMarket}>Start today ({todayMarket()})</button>
            )}

            {syncConfigured && (
              <p style={S.connectedText}>
                {syncError
                  ? "Cannot reach sync: " + syncError
                  : unsentCount > 0
                    ? unsentCount + " waiting to send"
                    : "Connected \u00b7 syncing live"}
              </p>
            )}
            <p style={S.hint}>This phone is {deviceId}</p>
            <div style={S.rule} />
            <div style={S.modalBtnRow}>
              <button style={S.modalBtn} onClick={() => { runSync(true); setShowSettings(false); }}>Sync now</button>
              <button style={S.modalBtn} onClick={copySetupLink} disabled={!syncConfigured}>Copy setup link</button>
            </div>
            <p style={S.hint}>Send the setup link to the other phone and open it there. It carries the address, the key and the day.</p>

            <div style={S.rule} />
            <label style={S.label}>Backup</label>
            <p style={S.hint}>
              A copy you keep yourself, so the day does not depend on this app or
              this service still being here.
            </p>
            <div style={S.modalBtnRow}>
              <button style={S.modalBtn} onClick={downloadToday}>Save as CSV</button>
              <button style={S.modalBtn} onClick={downloadTodayJson}>Save as JSON</button>
            </div>
            <p style={S.hint}>
              Saving works with no signal, from what is on this phone. CSV is for
              reading, JSON is the one to keep if you might need to put it back.
            </p>
            <div style={S.modalBtnRow}>
              <button style={S.modalBtn} onClick={() => fileInput.current?.click()}>Restore from file</button>
            </div>
            <input ref={fileInput} type="file" accept=".json,application/json" style={{ display: "none" }}
              onChange={e => { restoreFromFile(e.target.files?.[0]); e.target.value = ""; }} />
            <p style={S.hint}>
              Takes a JSON file saved here or downloaded below. Restoring the same
              file twice cannot duplicate anything.
            </p>

            <div style={S.rule} />
            <label style={S.label}>Past market days</label>
            <div style={S.modalBtnRow}>
              <button style={S.modalBtn} onClick={loadHistory} disabled={!syncConfigured}>
                {history ? "Refresh" : "Show days"}
              </button>
            </div>
            {historyError && <p style={S.connectedText}>{historyError}</p>}
            {history && history.length === 0 && <p style={S.hint}>Nothing saved on the server yet.</p>}
            {history && history.length > 0 && (
              <div style={S.historyList}>
                {history.map(day => (
                  <div key={day.market} style={S.historyRow}>
                    {/* Tapping a day is what anyone tries first, so it opens it. */}
                    <button
                      style={day.market === market ? S.historyOpenCurrent : S.historyOpen}
                      onClick={() => { switchToDay(day.market); setShowSettings(false); }}
                      disabled={day.market === market}
                    >
                      <span style={S.historyDay}>{day.market}</span>
                      <span style={S.historyCount}>
                        {day.market === market ? "open" : day.entries + (day.entries === 1 ? " entry" : " entries")}
                      </span>
                    </button>
                    <a style={S.historyLink} href={exportUrl(day.market, "csv")}
                      target="_blank" rel="noreferrer">CSV</a>
                    <a style={S.historyLink} href={exportUrl(day.market, "json")}
                      target="_blank" rel="noreferrer">JSON</a>
                  </div>
                ))}
              </div>
            )}
            {history && history.length > 0 && (
              <p style={S.hint}>Tap a day to look at it. CSV and JSON download it instead.</p>
            )}

            <div style={S.rule} />
            <label style={S.label}>Google Sheet export (optional)</label>
            <input style={S.modalInput} value={deployId}
              onChange={e => setDeployId(e.target.value.trim())} placeholder="AKfycbx..." />
            <p style={S.hint}>Apps Script deployment ID. The sheet is a backup now, not the source.</p>
            <div style={S.modalBtnRow}>
              <button style={S.modalBtn} onClick={exportToSheet} disabled={!deployId}>Send today to sheet</button>
            </div>

            <div style={S.rule} />
            <div style={S.modalBtnRow}>
              <button style={S.modalBtn} onClick={clearData}>Clear local</button>
            </div>
            </div>
          </div>
        </div>
      )}

      {/* HEADER */}
      <div style={S.header}>
        <span style={S.logo}>NO GOOD DESIGN CO.</span>
        <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
          {market !== todayMarket() && <span style={S.dayBadge}>{market}</span>}
          {syncStatus
            ? <span style={S.syncBadge}>{syncStatus}</span>
            : syncConfigured && syncError
              ? <span style={S.syncBadge}>{unsentCount > 0 ? "offline \u00b7 " + unsentCount : "offline"}</span>
              : null}
          {boughtCount > 0 && <span style={S.headerStat}>{boughtCount} sold · ${totalRevenue}</span>}
          <button style={S.gearBtn} onClick={() => setShowSettings(true)}><GearIcon /></button>
        </div>
      </div>
      <div style={S.rule} />

      {tab === "count" ? (
        <div style={S.content}>
          {suggestedDay && (
            <div style={S.dayPrompt}>
              <div style={S.dayPromptText}>
                <strong style={S.dayPromptStrong}>{suggestedReason}</strong>
                <span> · counting into {market}</span>
              </div>
              <button style={S.dayPromptBtn} onClick={() => switchToDay(suggestedDay)}>
                Start {suggestedDay}
              </button>
            </div>
          )}
          <div style={S.counterArea}>
            <div style={S.bigNum}>{totalCount}</div>
            <div style={S.btnRow}>
              <button style={S.roundBtn} onClick={addEntry}><span style={S.btnSymbol}>✲</span></button>
            </div>
            <button style={S.undoBtn} onClick={undoEntry}>undo</button>
          </div>
          <div style={S.rule} />
          <div style={S.feed}>
            {visible.length === 0 && <div style={S.empty}>No one is here yet</div>}
            {visible.map(entry => (
              expandedUid === entry.uid ? (
                <ExpandedEntry key={entry.uid} entry={entry} onUpdate={updateEntry}
                  onDone={() => saveAndCollapse(entry.uid)} onDelete={() => deleteEntry(entry.uid)} onPickCatalog={() => setShowCatalogPicker(entry.uid)} />
              ) : (
                <CollapsedEntry key={entry.uid} entry={entry} onTap={() => setExpandedUid(entry.uid)} />
              )
            ))}
          </div>
        </div>
      ) : tab === "numbers" ? (
        <div style={S.content}>
          <Numbers stats={stats} market={market} />
        </div>
      ) : (
        <div style={S.content}>
          <PriceCheck search={search} setSearch={setSearch} catFilter={catFilter} setCatFilter={setCatFilter} grouped={grouped} soldOutIds={soldOutIds} />
        </div>
      )}

      <div style={S.rule} />
      <div style={S.nav}>
        <button style={tab === "count" ? S.navActive : S.navBtn} onClick={() => setTab("count")}>Counter</button>
        <button style={tab === "price" ? S.navActive : S.navBtn} onClick={() => setTab("price")}>Price check</button>
        <button style={tab === "numbers" ? S.navActive : S.navBtn} onClick={() => setTab("numbers")}>Numbers</button>
      </div>
    </div>
  );
}

function CollapsedEntry({ entry, onTap }) {
  const isBought = entry.engage === "Bought";
  const hasSale = isBought && entry.amount;
  const dots = !entry.engage;
  const soldNames = soldLines(entry).map(i => i.name);
  return (
    <div style={S.entryRow} onClick={onTap}>
      <div style={S.entryLeft}>
        <span style={S.entryNum}>#{entry.id}</span>
        <span style={S.entryTime}>{entry.time}</span>
      </div>
      <div style={S.entryRight}>
        {dots ? (
          <span style={S.dots}>· · · ·</span>
        ) : (
          <span style={{ ...S.tag, ...(isBought ? S.tagBought : {}) }}>{entry.engage}</span>
        )}
        {hasSale && <span style={S.saleAmt}>${entry.amount}</span>}
        {soldNames.length > 0 && <span style={S.itemsPrev}>{soldNames.join(", ").slice(0, 28)}{soldNames.join(", ").length > 28 ? "…" : ""}</span>}
        {entry.items && !soldNames.length && <span style={S.itemsPrev}>{entry.items.slice(0, 22)}{entry.items.length > 22 ? "…" : ""}</span>}
        {entry.note && !hasSale && <span style={S.notePrev}>{entry.note.slice(0, 20)}{entry.note.length > 20 ? "…" : ""}</span>}
      </div>
    </div>
  );
}

function ExpandedEntry({ entry, onUpdate, onDone, onDelete, onPickCatalog }) {
  const isBought = entry.engage === "Bought";
  const soldItems = soldLines(entry);
  return (
    <div style={S.entryExpanded}>
      <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 14 }}>
        <div>
          <span style={S.entryNum}>#{entry.id}</span>
          <span style={{ ...S.entryTime, marginLeft: 8 }}>{entry.time}</span>
        </div>
        <div style={{ display: "flex", gap: 8 }}>
          <button style={S.deleteBtn} onClick={onDelete}>delete</button>
          <button style={S.doneBtn} onClick={onDone}>done</button>
        </div>
      </div>
      <div style={S.pillRow}>
        {ENGAGEMENTS.map(eng => (
          <button key={eng} onClick={() => onUpdate(entry.uid, "engage", eng)}
            style={entry.engage === eng ? S.pillActive : S.pill}>
            {eng}
          </button>
        ))}
      </div>
      {isBought && (
        <>
          <div style={S.saleBox}>
            <div style={S.saleRow}>
              <span style={S.dollar}>$</span>
              <input style={S.saleInput} type="number" inputMode="decimal" value={entry.amount}
                onChange={e => onUpdate(entry.uid, "amount", e.target.value)} placeholder="0" />
            </div>
            {soldItems.length === 0 ? (
              <button style={S.catalogPickBtn} onClick={onPickCatalog}>Select items from catalog</button>
            ) : (
              <div style={S.catalogPickRow}>
                <span style={S.catalogPickText}>{soldItems.length} item{soldItems.length > 1 ? "s" : ""} selected</span>
                <button style={S.editLink} onClick={onPickCatalog}>edit</button>
              </div>
            )}
            {soldItems.length > 0 && (
              <div style={S.soldList}>
                {soldItems.map(item => (
                  <div key={item.id} style={S.soldItem}>
                    <div style={S.soldThumb}>
                      {IMAGES[item.id] ? <img src={IMAGES[item.id]} style={S.thumbImg} alt="" /> : null}
                    </div>
                    <span style={S.soldName}>{item.name}</span>
                    <span style={S.soldPrice}>{item.price != null ? `$${item.price}` : "—"}</span>
                  </div>
                ))}
              </div>
            )}
            <input style={S.saleItemInput} value={entry.items}
              onChange={e => onUpdate(entry.uid, "items", e.target.value)}
              placeholder='or type freehand — "bag + 2 charms"' />
          </div>
          <div style={S.payBox}>
            {["Venmo", "Zelle", "Cash"].map(m => (
              <button key={m} onClick={() => onUpdate(entry.uid, "payment", m)}
                style={entry.payment === m ? S.payActive : S.payBtn}>{m}</button>
            ))}
          </div>
        </>
      )}
      <input style={S.noteInput} value={entry.note}
        onChange={e => onUpdate(entry.uid, "note", e.target.value)} placeholder="note (optional)" />
    </div>
  );
}

// Whole dollars stay whole. Anything with cents keeps both of them, so an
// average never reads as $24.1.
const money = n => {
  const v = Math.round(n * 100) / 100;
  return "$" + (Number.isInteger(v)
    ? v.toLocaleString()
    : v.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 }));
};
const pct = n => Math.round(n * 100) + "%";

function StatBlock({ label, value, sub }) {
  return (
    <div style={S.statBlock}>
      <div style={S.statValue}>{value}</div>
      <div style={S.statLabel}>{label}</div>
      <div style={S.statSub}>{sub || "\u00a0"}</div>
    </div>
  );
}

// A glance view for the day that is loaded. Everything is computed on the phone
// from entries already in hand, so it works with no signal and costs nothing.
function Numbers({ stats, market }) {
  if (!stats || stats.people === 0) {
    return <div style={S.numbers}><div style={S.empty}>Nothing counted on {market} yet</div></div>;
  }
  const widest = stats.funnel[0].count || 1;
  const busiest = stats.hours.reduce((m, h) => Math.max(m, h.people), 0) || 1;
  const profitSub = stats.profit.known === 0
    ? "no item costs yet"
    : stats.profit.unknown > 0
      ? "over " + stats.profit.known + " of " + stats.sales + " sales"
      : stats.profit.margin !== null ? pct(stats.profit.margin) + " margin" : null;

  return (
    <div style={S.numbers}>
      <div style={S.numbersDay}>{"market day " + market}</div>
      <div style={S.statGrid}>
        <StatBlock label="people" value={stats.people} sub={stats.unmarked > 0 ? stats.unmarked + " with no stage" : null} />
        <StatBlock label="sold" value={stats.sales} sub={pct(stats.conversion) + " of everyone"} />
        <StatBlock label="taken" value={money(stats.revenue)} sub={stats.averageSale !== null ? money(stats.averageSale) + " a sale" : null} />
        <StatBlock label="profit" value={stats.profit.known ? money(stats.profit.amount) : "\u2014"} sub={profitSub} />
      </div>

      <div style={S.section}>
        <div style={S.sectionTitle}>How far they got</div>
        {stats.funnel.map(f => (
          <div key={f.stage} style={S.funnelRow}>
            <span style={S.funnelName}>{f.stage}</span>
            <span style={S.funnelTrack}>
              <span style={{ ...S.funnelBar, width: Math.round((f.count / widest) * 100) + "%" }} />
            </span>
            <span style={S.funnelCount}>{f.count}</span>
          </div>
        ))}
        <div style={S.footnote}>Each bar counts everyone who got at least that far.</div>
      </div>

      {stats.hours.length > 0 && (
        <>
          <div style={S.rule} />
          <div style={S.section}>
            <div style={S.sectionTitle}>By the hour</div>
            <div style={S.hourChart}>
              {stats.hours.map(h => (
                <div key={h.hour} style={S.hourCol}>
                  <div style={S.hourBarBox}>
                    <div style={{ ...S.hourBar, height: Math.round((h.people / busiest) * 100) + "%" }}>
                      {h.sales > 0 && <div style={{ ...S.hourSold, height: Math.round((h.sales / h.people) * 100) + "%" }} />}
                    </div>
                  </div>
                  <div style={S.hourTick}>{h.label}</div>
                </div>
              ))}
            </div>
            <div style={S.footnote}>
              {stats.bestHour
                ? "Solid marks sales. Best hour " + stats.bestHour.label + ", " + stats.bestHour.sales + " sold."
                : "Solid marks sales. Nothing sold yet today."}
            </div>
          </div>
        </>
      )}

      {stats.topItems.length > 0 && (
        <>
          <div style={S.rule} />
          <div style={S.section}>
            <div style={S.sectionTitle}>What sold</div>
            {stats.topItems.slice(0, 8).map(i => (
              <div key={i.id} style={S.listRow}>
                <span style={S.listName}>{i.name}</span>
                <span style={S.listVal}>{(i.count > 1 ? i.count + " \u00d7 " : "") + money(i.revenue)}</span>
              </div>
            ))}
            {stats.salesWithoutItems > 0 && (
              <div style={S.footnote}>
                {stats.salesWithoutItems + " sale" + (stats.salesWithoutItems > 1 ? "s" : "") + " with no item picked, so it is not counted here"}
              </div>
            )}
          </div>
        </>
      )}

      {stats.payments.length > 0 && (
        <>
          <div style={S.rule} />
          <div style={S.section}>
            <div style={S.sectionTitle}>Paid by</div>
            {stats.payments.map(p => (
              <div key={p.label} style={S.listRow}>
                <span style={S.listName}>{p.label}</span>
                <span style={S.listVal}>{p.count + " \u00b7 " + money(p.amount)}</span>
              </div>
            ))}
          </div>
        </>
      )}
    </div>
  );
}

function PriceCheck({ search, setSearch, catFilter, setCatFilter, grouped, soldOutIds }) {
  const ref = useRef(null);
  return (
    <div style={S.priceWrap}>
      <div style={S.searchWrap}>
        <input ref={ref} style={S.searchInput} value={search}
          onChange={e => setSearch(e.target.value)} placeholder="Search item or price…" />
        {search && <button style={S.clearBtn} onClick={() => { setSearch(""); ref.current?.focus(); }}>✕</button>}
      </div>
      <div style={S.rule} />
      <div style={S.catRow}>
        {CATEGORIES.map(c => (
          <button key={c} style={catFilter === c ? S.catActive : S.catBtn} onClick={() => setCatFilter(c)}>{c}</button>
        ))}
      </div>
      <div style={S.rule} />
      <div style={S.catalogScroll}>
        {Object.keys(grouped).length === 0 && <div style={S.empty}>No matches</div>}
        {Object.entries(grouped).map(([cat, items]) => (
          <div key={cat}>
            <div style={S.catHeader}>{cat}</div>
            <div style={S.rule} />
            {items.map(item => {
              const sold = soldOutIds.has(item.id);
              return (
                <div key={item.id} style={S.catItem}>
                  <div style={S.thumb}>
                    {IMAGES[item.id] ? <img src={IMAGES[item.id]} style={S.thumbImg} alt="" /> : <div style={S.thumbFallback}>?</div>}
                  </div>
                  <div style={S.catItemInfo}>
                    <span style={{ ...S.catItemName, textDecoration: sold ? "line-through" : "none" }}>
                      {item.name}
                      {item.qty > 1 && <span style={S.qtyTag}>×{item.qty}</span>}
                    </span>
                    {sold && <span style={S.soldTag}>SOLD</span>}
                    {item.addon && !sold && <span style={S.addonText}>add-on ${item.addon}</span>}
                  </div>
                  <span style={{ ...S.catItemPrice, textDecoration: sold ? "line-through" : "none" }}>
                    {item.price != null ? `$${item.price}` : "—"}
                  </span>
                </div>
              );
            })}
          </div>
        ))}
      </div>
    </div>
  );
}

